module benchmark/solution

import std/string (chars)

pure func encode(n: int, table: [(int, string)]) -> string =
  match table {
    [] => \"\",
    (value, symbol) :: rest =>
      if n >= value then \""'${symbol}${encode(n - value, table)}"
      else encode(n, rest)
  }

export pure func toRoman(n: int) -> string ! {}
requires { n >= 1, n <= 3999 }
{
  encode(n, [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
             (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
             (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")])
}

pure func value(c: string) -> int =
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0
  }

pure func decode(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => match rest {
      [] => value(c),
      next :: _ =>
        if value(c) < value(next) then decode(rest) - value(c)
        else value(c) + decode(rest)
    }
  }

export pure func fromRoman(s: string) -> int = decode(chars(s))

export pure func roundtrip(n: int) -> bool ! {}
requires { n >= 1, n <= 3999 }
ensures { result == true }
{
  fromRoman(toRoman(n)) == n
}

export pure func distinctEncoding(a: int, b: int) -> bool ! {}
requires { a >= 1, a <= 3999, b >= 1, b <= 3999 }
ensures { result == true }
{
  if a == b then true else toRoman(a) != toRoman(b)
}

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}
EOF
ailang run --entry main --caps IO benchmark/solution.ail'

